package repository
import("context";"errors";"fmt";"q08-money-transfer/model";"github.com/jackc/pgx/v5";"github.com/jackc/pgx/v5/pgxpool")
var ErrAccountNotFound=errors.New("account not found");var ErrInsufficientBalance=errors.New("insufficient balance")
type AccountRepositoryImpl struct{db *pgxpool.Pool}
func NewAccountRepository(db *pgxpool.Pool)AccountRepository{return &AccountRepositoryImpl{db}}
func(r *AccountRepositoryImpl)GetAccount(id int)(*model.Account,error){var a model.Account;e:=r.db.QueryRow(context.Background(),`SELECT id,account_number,holder_name,balance FROM accounts WHERE id=$1`,id).Scan(&a.ID,&a.AccountNumber,&a.HolderName,&a.Balance);if e==pgx.ErrNoRows{return nil,ErrAccountNotFound};return &a,e}
func(r *AccountRepositoryImpl)Transfer(from,to int,amount float64)error{if amount<=0{return errors.New("amount must be greater than zero")};tx,e:=r.db.Begin(context.Background());if e!=nil{return e};defer tx.Rollback(context.Background());var b float64;e=tx.QueryRow(context.Background(),`SELECT balance FROM accounts WHERE id=$1 FOR UPDATE`,from).Scan(&b);if e==pgx.ErrNoRows{return ErrAccountNotFound};if e!=nil{return e};if b<amount{return ErrInsufficientBalance};var x int;e=tx.QueryRow(context.Background(),`SELECT id FROM accounts WHERE id=$1 FOR UPDATE`,to).Scan(&x);if e==pgx.ErrNoRows{return ErrAccountNotFound};if e!=nil{return e};if _,e=tx.Exec(context.Background(),`UPDATE accounts SET balance=balance-$1 WHERE id=$2`,amount,from);e!=nil{return e};if _,e=tx.Exec(context.Background(),`UPDATE accounts SET balance=balance+$1 WHERE id=$2`,amount,to);e!=nil{return e};if e=tx.Commit(context.Background());e!=nil{return e};fmt.Println("Transfer committed successfully");return nil}
